sp_widget.client_script:
api.controller = function($scope) {
    var c = this;

    c.form = {
        hallId: '',
        startDate: '',
        endDate: '',
        purpose: ''
    };

    c.availabilityMessage = '';
    c.isAvailable = false;
    c.successMessage = '';
    c.errorMessage = '';

    // Check Availability
    c.checkAvailability = function() {
        c.availabilityMessage = '';
        c.isAvailable = false;

        if (!c.form.hallId || !c.form.startDate || !c.form.endDate) {
            c.availabilityMessage = 
            'Please select a hall, start date, and end date first.';
            return;
        }

        if (c.form.endDate <= c.form.startDate) {
            c.availabilityMessage = 
            'End Date must be after Start Date.';
            return;
        }

        var ga = new GlideAjax('SportsHallAvailabilityAjax');
        ga.addParam('sysparm_name', 'checkAvailability');
        ga.addParam('sysparm_hall_id', c.form.hallId);
        ga.addParam('sysparm_start_date', c.form.startDate);
        ga.addParam('sysparm_end_date', c.form.endDate);

        ga.getXMLAnswer(function(response) {
            if (response == 'available') {
                c.availabilityMessage = 'Hall is available for your selected dates!';
                c.isAvailable = true;
            } else {
                c.availabilityMessage = 
                'Sorry, this hall is already booked for the selected time.';
                c.isAvailable = false;
            }
            $scope.$apply();
        });
    };

    // Submit Booking
    c.submitBooking = function() {
        if (!c.isAvailable) {
            c.errorMessage = 'Please check availability first.';
            return;
        }

        c.server.get({
            action: 'submitBooking',
            hallId: c.form.hallId,
            startDate: c.form.startDate,
            endDate: c.form.endDate,
            purpose: c.form.purpose
        }).then(function(response) {
            if (response.data.result == 'success') {
                c.successMessage = 
                'Booking submitted successfully! Reference: ' 
                + response.data.number;
                c.errorMessage = '';
                // Reset form
                c.form = {
                    hallId: '',
                    startDate: '',
                    endDate: '',
                    purpose: ''
                };
                c.isAvailable = false;
                c.availabilityMessage = '';
            } else {
                c.errorMessage = 'Error submitting booking. Please try again.';
            }
            $scope.$apply();
        });
    };
};

sp_widget.css:
.booking-form-container {
  padding: 25px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);

  h3 {
    color: #00695C;
    font-weight: bold;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 2px solid #00695C;
  }

  label {
    color: #333;
    font-size: 13px;
    margin-bottom: 5px;
  }

  .form-control {
    border-radius: 8px;
    border: 1px solid #ddd;

    &:focus {
      border-color: #00695C;
      box-shadow: 0 0 5px rgba(0,105,92,0.3);
    }
  }

  .btn-info {
    background: #00838F;
    border: none;
    border-radius: 20px;
    padding: 8px 20px;

    &:hover {
      background: #006064;
    }
  }

  .btn-primary {
    background: #00695C;
    border: none;
    border-radius: 8px;
    padding: 12px;
    font-size: 15px;
    font-weight: bold;
    margin-top: 10px;

    &:hover {
      background: #004D40;
    }

    &:disabled {
      background: #B2DFDB;
      cursor: not-allowed;
    }
  }
}

sp_widget.script:
(function() {
    // Handle booking submission
    if (input && input.action == 'submitBooking') {
        var gr = new GlideRecord(
            'x_1954179_sports_0_sports_hall_booking'
        );
        gr.initialize();
        gr.setValue('sports_hall', input.hallId);
        gr.setValue('requested_by', gs.getUserID());
        gr.setValue('start_date', input.startDate);
        gr.setValue('end_date', input.endDate);
        gr.setValue('purpose', input.purpose);
        gr.setValue('status', 'Pending');
        var sysId = gr.insert();

        if (sysId) {
            // Get the booking number
            var booking = new GlideRecord(
                'x_1954179_sports_0_sports_hall_booking'
            );
            booking.get(sysId);
            data.result = 'success';
            data.number = booking.getValue('number');
        } else {
            data.result = 'error';
        }
        return;
    }

    // Load sports halls for dropdown
    var gr = new GlideRecord('x_1954179_sports_0_sports_hall');
    gr.addQuery('available', true);
    gr.orderBy('hall_name');
    gr.query();

    data.halls = [];
    while (gr.next()) {
        data.halls.push({
            sys_id: gr.getUniqueValue(),
            name: gr.getValue('hall_name')
        });
    }
})();
